import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# C++ source for the custom matrix multiplication kernel (C = A.T @ B)
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A is (K, M), B is (K, N)
            int row = idx / N;
            int col = idx % N;
            float a_val = A[k * M + row];
            float b_val = B[k * N + col];
            sum += a_val * b_val;
        }
        C[idx] = sum;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int K = A.size(0);
    int M = A.size(1); // columns of A
    int N = B.size(1);

    auto C = torch::zeros(M, N, device=A.device(), dtype=A.dtype());
    float* C_ptr = C.data_ptr<float>();

    const int block_size = 256;
    const int num_blocks = (M * N + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, C_ptr, M, K, N);

    return C;
}
"""

cpp_source = "torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B);"

custom_matmul = load_inline(
    name="custom_matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["custom_matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.custom_matmul = custom_matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.custom_matmul(A, B)
